  (* [comment removed for export] *)
  Definition astrlen_postZ (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (SP W : Z) (str slack : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (Z.of_nat (length str))) a1 a2 a3 a4 a5 a6 a7
                   s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom asegs)
      /\ munch [(SP - 4096, SP)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
      /\ stk asegs m' lo SP
      /\ bytes_at asegs m' W (str ++ b8 0 :: slack)
      /\ ACONST m'.

  Lemma astrlen_specZ : forall ra gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (SP W : Z) (str slack : list byte) (lo : Z),
    bytes_at asegs m W (str ++ b8 0 :: slack) -> ~ In (b8 0) str ->
    ((- (W + Z.of_nat (length str) + 1)) mod 8 <= Z.of_nat (length slack)) ->
    accessible m W (Z.of_nat (length str) + 1) -> shvis m W (W + Z.of_nat (length str) + 1) ->
    in_app_mem W (W + Z.of_nat (length str) + 1) -> Z.of_nat (length str) + 1 <= 2^40 ->
    stk asegs m lo SP -> aceil <= lo -> lo <= SP - 4096 -> SP < 2^64 ->
    (W + Z.of_nat (length str) + 1 + Z.of_nat (length slack) <= lo \/ SP <= W) ->
    mem_inv asegs m -> ACONST m ->
    evt asegs (astrlen_postZ ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc SP W str slack lo m)
      (MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 W) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 ASTRLEN_STUB) fc None m (seg_rom asegs)).
